xhtml:body.xhtml:script:
//
  window.changeColor = function() {
    console.log("Button clicked! Attempting to change color...");

    // Target documentElement (the <html> tag) instead of body
    const root = document.documentElement;

    if (root) {
      const colors = ['#1a1a1a', '#2d1b2e', '#1b2d2b', '#2d2b1b', '#1b1b2d', '#2b1b1b'];
      const randomColor = colors[Math.floor(Math.random() * colors.length)];
      root.style.backgroundColor = randomColor;
      console.log("Color changed to: " + randomColor);
    } else {
      console.error("Could not find document element");
    }
  };

  // Auto-resize logic
  window.addEventListener('resize', function() {
      var w = window.innerWidth;
      var h = window.innerHeight;
      var svg = document.querySelector('svg');
      var fo = document.querySelector('foreignObject');
      if(svg) {
          svg.setAttribute('width', w);
          svg.setAttribute('height', h);
          svg.setAttribute('viewBox', '0 0 ' + w + ' ' + h);
      }
      if(fo) {
          fo.setAttribute('width', w);
          fo.setAttribute('height', h);
      }
  });
//
